    import re
    def body(s):  # 「解答例：」から最初の（字数）までの本文
        m = re.search(r"解答例：(.*?)（\d+字）", s)
        return m.group(1) if m else None
    c1 = body(items[8]["a"]); assert c1 and len(c1) <= 80, len(c1)
    c2 = body(items[9]["a"]); assert c2 and len(c2) <= 100, len(c2)
